def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(v, default=0):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return int(v[0]), int(v[1])
        return default, default

    def clamp_step(a, b):
        return sgn(b - a)

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position", (0, 0)))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)))
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return [clamp_step(sx, ox), clamp_step(sy, oy)]
        corners = [(0, 0)]
        if h:
            corners.append((0, h - 1))
        if w:
            corners.append((w - 1, 0))
        if w and h:
            corners.append((w - 1, h - 1))
        if corners:
            target = max(corners, key=lambda c: dist(c, (ox, oy)))
            return [clamp_step(sx, target[0]), clamp_step(sy, target[1])]
        return [-clamp_step(sx, ox), -clamp_step(sy, oy)]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        candidates = []
        for item in targets:
            if isinstance(item, (list, tuple)) and len(item) >= 2:
                candidates.append((int(item[0]), int(item[1])))
        if candidates:
            best = min(candidates, key=lambda c: dist((sx, sy), c) + 0.35 * dist((ox, oy), c))
            return [clamp_step(sx, best[0]), clamp_step(sy, best[1])]
        if w and h:
            center = (w // 2, h // 2)
            return [clamp_step(sx, center[0]), clamp_step(sy, center[1])]
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    candidates = []
    for item in resources:
        if isinstance(item, dict):
            p = item.get("position", item.get("pos", item.get("location")))
            x, y = pos(p, None) if p is not None else (None, None)
            if x is None:
                continue
            val = item.get("value", item.get("amount", 1))
            candidates.append((x, y, val))
        elif isinstance(item, (list, tuple)) and len(item) >= 2:
            if len(item) >= 3 and isinstance(item[2], (int, float)):
                candidates.append((int(item[0]), int(item[1]), item[2]))
            else:
                candidates.append((int(item[0]), int(item[1]), 1))

    if candidates:
        def score(c):
            d = dist((sx, sy), (c[0], c[1]))
            od = dist((ox, oy), (c[0], c[1]))
            return d - 0.25 * float(c[2]) + 0.15 * max(0, 8 - od)
        best = min(candidates, key=score)
        return [clamp_step(sx, best[0]), clamp_step(sy, best[1])]

    if w and h:
        cx, cy = w // 2, h // 2
        return [clamp_step(sx, cx) or (-clamp_step(sx, ox)), clamp_step(sy, cy) or (-clamp_step(sy, oy))]

    return [clamp_step(sx, ox), clamp_step(sy, oy)]

